function announceStation(departure=false){if(muted||document.hidden)return;const announcement=$('hindiAnnouncement');if(!announcement.paused)return;const index=departure?0:1+(announcementIndex++%2);announcement.src=stationAnnouncements[index];announcement.volume=.85;announcement.currentTime=0;nextAnnouncement=performance.now()+45000;announcement.play().catch(()=>{if(!window.speechSynthesis)return;const u=new SpeechSynthesisUtterance(stationPhrases[index]);u.lang='hi-IN';const voice=window.speechSynthesis.getVoices().find(v=>/^hi/i.test(v.lang));if(voice)u.voice=voice;u.volume=1;u.rate=.86;window.speechSynthesis.speak(u)})}
function updateAmbience(now){if(!ambience||muted||document.hidden||audioContext.state!=='running')return;const t=now/1000;const running=state==='departing',elapsed=Math.max(0,(now-departureStart)/1000);ambience.trackGain.gain.setTargetAtTime(running?.48:0,audioContext.currentTime,.4);ambience.track.playbackRate.setTargetAtTime(running?Math.min(3,.6+elapsed*.11):.6,audioContext.currentTime,.4);ambience.rumbleGain.gain.setTargetAtTime(state==='departing'?.42:state==='departed'?.035:.24,audioContext.currentTime,.7);ambience.motor.frequency.setTargetAtTime(state==='departing'?Math.min(110,52+(now-departureStart)*.002):52,audioContext.currentTime,.5);for(const v of ambience.voices){const phrase=Math.max(0,Math.sin(t*.78+v.phase))*.018,syllable=.3+.7*Math.max(0,Math.sin(t*8+v.phase));v.gain.gain.setTargetAtTime(phrase*syllable,audioContext.currentTime,.05);v.formant.frequency.setTargetAtTime(480+360*(1+Math.sin(t*1.35+v.phase)),audioContext.currentTime,.1)}if(now>nextAnnouncement){nextAnnouncement=now+75000;announceStation()}}
function horn(){if(!audioContext||muted||audioContext.state!=='running')return;const now=audioContext.currentTime;for(const delay of [0,2.1])for(const [frequency,volume] of [[311,.6],[370,.45],[466,.3]]){const o=audioContext.createOscillator(),g=audioContext.createGain(),f=audioContext.createBiquadFilter();o.type='sawtooth';o.frequency.value=frequency;f.type='lowpass';f.frequency.value=1000;o.connect(f);f.connect(g);g.connect(audioMaster);const t=now+delay;g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(volume,t+.1);g.gain.setValueAtTime(volume,t+1.35);g.gain.exponentialRampToValueAtTime(.001,t+1.7);o.start(t);o.stop(t+1.75)}}
function bell(){if(!audioContext||muted||audioContext.state!=='running')return;const now=audioContext.currentTime;for(let strike=0;strike<2;strike++)for(let [freq,vol] of [[784,.16],[1568,.065],[2133,.025]]){const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;o.connect(g);g.connect(audioMaster);const start=now+strike*.58;g.gain.setValueAtTime(.001,start);g.gain.exponentialRampToValueAtTime(vol,start+.012);g.gain.exponentialRampToValueAtTime(.001,start+1.8);o.start(start);o.stop(start+1.85)}}
$('soundToggle').addEventListener('click',()=>{soundPreferenceSet=true;muted=!muted;unlockAudio();applyMute();if(!muted){announceStation();nextAnnouncement=performance.now()+75000}});document.addEventListener('visibilitychange',applyMute);window.addEventListener('pagehide',()=>{if(audioContext)audioContext.suspend();if(window.speechSynthesis)window.speechSynthesis.cancel()});
function scan(){if(!ready||state!=='idle')return;enableInspectionAudio();$('depart').hidden=true;state='scanning';scanStart=performance.now();setThermal(false);sceneEl.classList.add('scanning');setTrackPosition(scanRear);scanGroup.visible=true;scanGroup.position.x=scanRear;lockScenarios(true);$('scan').disabled=true;$('scan').hidden=false;$('scanButtonText').textContent=rescanning?'Verifying clearance…':'Inspecting all coaches…';$('scanLabel').textContent=rescanning?'Verification scan':'Inspecting all coaches…';status(rescanning?'Staff clearance complete. AI is checking every coach again.':'AI is inspecting the selected hazards. Staff will assist automatically.');$('banner').className='banner';sensor('Inspecting','scanning');$('coverage').textContent='Inspecting…';progress(0)}
function completeScan(now){sceneEl.classList.remove('scanning');scanGroup.visible=false;progress(100);$('coverage').textContent='All coaches inspected';if(hazardCount()){state='denied';detectedAt=now;setThermal(true);lockScenarios(true);setCameraDisabled(false);sensor('Hazard detected','hazard');$('scanLabel').textContent=hazardCount()+' hazards detected';$('scanButtonText').textContent='Staff responding…';status(hazardCount()+' hazards detected. Staff are responding; departure is blocked.');banner('Departure blocked · Staff responding to '+hazardCount()+' hazard'+(hazardCount()>1?'s':''),'danger');focusHazard()}else{state='cleared';lockScenarios(true);setCameraDisabled(false);document.querySelectorAll('[data-vehicle]').forEach(b=>b.disabled=false);$('scan').hidden=true;$('depart').hidden=false;$('depart').disabled=false;sensor('Clear','clear');$('scanLabel').textContent='Verification complete';$('scenarioHint').textContent='Selected scenarios resolved by staff.';status('AI verified all hazards are cleared. Confirm when the train is ready.');banner('All coaches clear · Ready for departure confirmation','success');cameraPreset('platform')}}
function depart(){if(state!=='cleared'||hazardCount())return;unlockAudio();applyMute();state='departing';departureStart=performance.now();lockScenarios(true);$('depart').disabled=true;$('depart').textContent='Train departing…';signalMat.color.set(0x73ffc0);signalMat.emissive.set(0x32f493);status('Departure confirmed. The train is leaving Platform 04.');banner('Dispatch approved · Train departing','success');$('hindiAnnouncement').pause();announceStation(true);bell();horn()}
function clearHazards(){if(state!=='denied')return;state='clearing';clearanceStart=performance.now();clearanceHazard=hazard;lockScenarios(true);$('scanButtonText').textContent='Staff clearing hazards…';$('scanLabel').textContent='Staff clearance';sensor('Staff on site','staff');status('Staff are guiding people and animals into the safe area.');setThermal(false);clearanceCameraStep=-1;staffCrew.forEach((p,i)=>{p.visible=[hasUnder(),hasLine(),hasAnimal()][i];p.position.set([hazardX.under-3,hazardX.line+10,hazardX.animal-6][i],.8,6)});$('banner').className='banner';progress(0)}
function updateClearance(now){if(state==='denied'&&now-detectedAt>=2200)clearHazards();if(state!=='clearing')return;const f=Math.min(1,(now-clearanceStart)/8000),approach=Math.min(1,f/.35),escort=Math.max(0,(f-.35)/.65),ease=escort*escort*(3-2*escort);const sites=[hasUnder()?hazardX.under:null,hasLine()?hazardX.line+7:null,hasAnimal()?hazardX.animal-4:null].filter(x=>x!==null),step=Math.min(sites.length-1,Math.floor(f*sites.length));if(step!==clearanceCameraStep){clearanceCameraStep=step;const x=sites[step];moveCamera([x,3.1,12],[x,1.5,2.5])}progress(f*100);staffCrew.forEach((p,i)=>{const startX=[hazardX.under-3,hazardX.line+10,hazardX.animal-6][i],endX=[hazardX.under-.8,hazardX.line+7.7,hazardX.animal-4.7][i],distance=[3.4,1.8,3.2][i];p.position.x=startX+(endX-startX)*approach;p.position.z=6-distance*approach+ease*distance;p.rotation.y=f<.35?Math.PI:0;p.userData.legs.forEach((leg,j)=>leg.rotation.x=Math.sin(now*.007+j*Math.PI)*.22)});if(hasUnder()){underPerson.position.set(hazardX.under-.78,.12+ease*.68,2.7+ease*2.8);underPerson.scale.setScalar(.85+ease*.15);underPerson.userData.arms.forEach(a=>a.rotation.x=2-ease*2);underPerson.quaternion.copy(underRest.quaternion).slerp(new THREE.Quaternion(),ease)}if(hasLine())linePerson.position.z=3.62+ease*2.1;if(hasAnimal()){animal.position.z=1.85+ease*3.9;animal.position.y=.12+ease*.68;animal.rotation.y=-Math.PI/2}if(f===1){hazard='none';updateHazard();restoreHazardPositions();state='idle';rescanning=true;scan()}}
function restoreHazardPositions(){underPerson.position.copy(underRest.position);underPerson.quaternion.copy(underRest.quaternion);underPerson.scale.setScalar(.85);underPerson.userData.arms.forEach(a=>a.rotation.x=2);linePerson.position.set(hazardX.line+7,.8,3.62);animal.position.set(hazardX.animal-4,.12,1.85);animal.rotation.y=0}
function reset(){state='idle';rescanning=false;detectedAt=0;staffCrew.forEach(p=>p.visible=false);restoreHazardPositions();$('scan').hidden=false;$('scan').disabled=!ready;$('depart').hidden=true;$('depart').textContent='Allow Departure';sceneEl.classList.remove('scanning');document.querySelectorAll('input[name=hazard]').forEach(el=>el.checked=true);document.querySelectorAll('[data-vehicle]').forEach(b=>b.setAttribute('aria-pressed','false'));$('coachInfo').textContent='1A × 1 · 2A × 2 · 3A × 3 · Sleeper × 4';hazard='under,line,animal';train.position.x=0;scanGroup.visible=false;signalMat.color.set(0xff584a);signalMat.emissive.set(0xff2415);lockScenarios(false);setThermal(false);updateHazard();cameraPreset('platform');$('banner').className='banner';status('');$('scanButtonText').textContent='Start Inspection';$('scanLabel').textContent='Pre-departure safety check';progress(0);$('progressText').textContent='Ready';$('coverage').textContent='Ready to inspect';sensor('Ready','ready');$('scenarioHint').textContent=''}
function scenarioChanged(changed){if(state!=='idle')return;const inputs=[...document.querySelectorAll('input[name=hazard]')];if(!inputs.some(el=>el.checked)){changed.checked=true;status('Keep at least one hazard selected for the simulation.');return}hazard=inputs.filter(el=>el.checked).map(el=>el.value).join(',');updateHazard();status(hazardCount()+' scenario'+(hazardCount()>1?'s':'')+' selected. Execute the scan to begin.');$('banner').className='banner';progress(0);$('progressText').textContent='Ready'}
document.querySelectorAll('input[name=hazard]').forEach(el=>el.addEventListener('change',()=>scenarioChanged(el)));$('depart').addEventListener('click',depart);
for(const c of [{code:'LOCO',type:'WAP-7',name:'Locomotive'},...coachSpec]){const b=document.createElement('button');b.dataset.vehicle=c.code;b.dataset.type=c.type;b.setAttribute('aria-pressed','false');b.title=c.name+(c.index?' · Coach '+c.index:'');b.setAttribute('aria-label',c.code+' · '+c.name+(c.index?' · Coach '+c.index:''));const title=document.createElement('span');title.textContent=c.code;const sub=document.createElement('small');sub.textContent=c.type;b.append(title,sub);b.addEventListener('click',()=>inspectVehicle(c.code));$('rakeButtons').append(b)}
$('scan').addEventListener('click',scan);$('reset').addEventListener('click',reset);$('normal').addEventListener('click',()=>setThermal(false));$('thermal').addEventListener('click',()=>setThermal(true));document.addEventListener('keydown',e=>{if(/INPUT|SELECT|BUTTON|TEXTAREA/.test(document.activeElement.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Space'){e.preventDefault();scan()}if(e.key.toLowerCase()==='r')reset()});
function resize(){const w=sceneEl.clientWidth,h=sceneEl.clientHeight;if(!w||!h)return;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(sceneEl);resize();controls.update();ready=true;$('scan').disabled=false;$('loading').hidden=true;reset();applyMute();
let last=performance.now();function animate(now){requestAnimationFrame(animate);if(now-last<32)return;const dt=Math.min((now-last)/1000,.05);last=now;if(state==='error'||document.hidden)return;
if(bannerExpires&&now>=bannerExpires){$('banner').className='banner';bannerExpires=0}updateAmbience(now);updateClearance(now);if(underPerson.visible&&state!=='clearing'){underPerson.userData.arms[1].rotation.x=2+Math.sin(now*.002)*.16;inspectionLight.position.set(hazardX.under-.78,1.1,1.1)}if(!reduced)for(const w of walkers){const phase=now*.00023+w.phase,swing=Math.sin(now*.004+w.phase)*.28;w.person.position.x=w.baseX+Math.sin(phase)*1.15;w.person.position.y=.81+Math.abs(Math.sin(now*.004+w.phase))*.012;w.person.rotation.y=Math.cos(phase)>0?Math.PI/2:-Math.PI/2;w.person.userData.arms.forEach((a,i)=>a.rotation.x=(i?1:-1)*swing);w.person.userData.legs.forEach((a,i)=>a.rotation.x=(i?-1:1)*swing)}if(cameraMove){const t=Math.min((now-cameraMove.start)/cameraMove.duration,1),k=t*t*(3-2*t);camera.position.lerpVectors(cameraMove.from,cameraMove.to,k);controls.target.lerpVectors(cameraMove.fromTarget,cameraMove.toTarget,k);if(t===1)cameraMove=null}
if(state==='scanning'){const f=Math.min((now-scanStart)/scanDuration,1);scanGroup.position.x=scanRear+f*(scanFront-scanRear);setTrackPosition(scanGroup.position.x);laserMat.opacity=.9+Math.sin(now*.01)*.1;progress(f*100);$('coverage').textContent=Math.round(f*100)+'% inspected';if(f>=1)completeScan(now)}
if(state==='departing'){const elapsed=Math.max(0,(now-departureStart)/1000-.9),distance=Math.min(departureDistance,.8*elapsed*elapsed);train.position.x=distance;for(const wheel of wheels)wheel.rotation.z-=dt*elapsed*1.6;if(distance>=departureDistance){state='departed';status('Departure complete · Platform clear','var(--mint)');$('scanButtonText').textContent='Train departed';$('depart').textContent='Train departed';banner('Departure complete · Platform 04 is clear','success');activity('Departure complete. Reset the demo to inspect another scenario.')}}
controls.update();updateTrackSlider();$('trainPosition').disabled=['scanning','clearing','departing'].includes(state);camera.updateMatrixWorld();for(const [id,obj,active] of [['hazardCallout',underPerson,ring.visible],['secondCallout',linePerson,lineRing.visible],['animalCallout',animal,animalRing.visible]]){if(!active)continue;const anchor=obj.position.clone();anchor.y+=id==='secondCallout'?2:1.15;const q=anchor.project(camera);$(id).style.left=Math.max(10,Math.min(90,(q.x*.5+.5)*100))+'%';$(id).style.top=Math.max(16,Math.min(80,(-q.y*.5+.5)*100))+'%';$(id).style.visibility=q.z>1||Math.abs(q.x)>.8||Math.abs(q.y)>.85?'hidden':'visible'} renderer.render(scene,camera)}requestAnimationFrame(animate);
